// PopulateEventMetadata stores pending event metadata (W3C SCXML 5.10).
// Note: event name is set separately via setCurrentEvent(); metadata supplies
// only the name the event ARRIVED under, when that is not its value's own.
func (p *SheetPeerPolicy) PopulateEventMetadata(meta *sce.EventMetadata) {
	// NL→IR Item C1 Path A: lift the dequeued event's typed payload from the
	// type-erased carrier into the typed policy field the native guards read
	// (twin of the C11 pop loop's `sm->pending_payload = evt.payload`).
	p.pendingPayloadTag = SheetPeerPayloadTagNone
	switch v := meta.TypedPayload.(type) {
	case SheetPeerSheetAddColPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetAddCol
		p.pendingSheetAddColPayload = v
	case SheetPeerSheetAddRowPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetAddRow
		p.pendingSheetAddRowPayload = v
	case SheetPeerSheetCellPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetCell
		p.pendingSheetCellPayload = v
	case SheetPeerSheetColPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetCol
		p.pendingSheetColPayload = v
	case SheetPeerSheetDropColPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetDropCol
		p.pendingSheetDropColPayload = v
	case SheetPeerSheetDropRowPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetDropRow
		p.pendingSheetDropRowPayload = v
	case SheetPeerSheetEditPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetEdit
		p.pendingSheetEditPayload = v
	case SheetPeerSheetFormulaPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetFormula
		p.pendingSheetFormulaPayload = v
	case SheetPeerSheetGonePayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetGone
		p.pendingSheetGonePayload = v
	case SheetPeerSheetGoneColPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetGoneCol
		p.pendingSheetGoneColPayload = v
	case SheetPeerSheetJoinPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetJoin
		p.pendingSheetJoinPayload = v
	case SheetPeerSheetRowPayload:
		p.pendingPayloadTag = SheetPeerPayloadTagSheetRow
		p.pendingSheetRowPayload = v
	}

	p.pendingEventData = meta.Data
	p.pendingEventInvokeid = meta.InvokeID
}

